import { Type } from "typebox";
import { Check } from "typebox/value";

export type TaskId = string & { readonly __brand: "TaskId" };
export type ChildPlacement = "tab" | "split";
export type ChildThinkingLevel = "off" | "minimal" | "low" | "medium" | "high" | "xhigh" | "max";
export type SelectionSource = "explicit" | "role" | "default" | "parent";

export interface ModelReference {
  provider: string;
  id: string;
}

export interface SpawnTask {
  prompt: string;
  placement?: ChildPlacement;
  role?: string;
  model?: string;
  thinking?: ChildThinkingLevel;
}

export interface SpawnBatchRequest {
  tasks: SpawnTask[];
}

export type ChildStatus = "succeeded" | "failed" | "blocked" | "unattributable" | "parent_aborted";

export interface ChildLocation {
  workspaceId: string;
  tabId: string;
  paneId: string;
}

export interface ChildRuntimeSelection {
  model?: ModelReference;
  modelSource?: SelectionSource;
  thinkingLevel?: ChildThinkingLevel;
  thinkingSource?: SelectionSource;
  rolePrompt?: string;
}

export interface ChildResult {
  taskId: TaskId;
  requestIndex: number;
  status: ChildStatus;
  summary?: string;
  truncated: boolean;
  sessionId?: string;
  sessionPath?: string;
  location?: ChildLocation;
  paneClosed: boolean;
  role?: string;
  selection?: Omit<ChildRuntimeSelection, "rolePrompt">;
  error?: {
    code:
      | "role_not_found"
      | "model_routing_failed"
      | "start_failed"
      | "prompt_failed"
      | "result_unreadable"
      | "blocked"
      | "parent_aborted";
    message: string;
  };
}

export interface SpawnBatchResult {
  requested: number;
  results: ChildResult[];
}

export interface ParentContext {
  cwd: string;
  parentLabel?: string;
  model?: ModelReference;
  thinkingLevel?: ChildThinkingLevel;
}

export interface BatchProgress {
  completed: number;
  total: number;
  /** Settled children only, in request order. */
  results: ChildResult[];
}

export class RequestValidationError extends Error {}

const TextSchema = Type.String();
const ChildPlacementSchema = Type.Union([Type.Literal("tab"), Type.Literal("split")]);
const ChildThinkingLevelSchema = Type.Union([
  Type.Literal("off"),
  Type.Literal("minimal"),
  Type.Literal("low"),
  Type.Literal("medium"),
  Type.Literal("high"),
  Type.Literal("xhigh"),
  Type.Literal("max"),
]);

export function validateSpawnBatchRequest(request: SpawnBatchRequest): void {
  if (!Array.isArray(request.tasks) || request.tasks.length < 1 || request.tasks.length > 8) {
    throw new RequestValidationError("tasks must contain between 1 and 8 tasks");
  }
  request.tasks.forEach((task, index) => {
    if (!task || !Check(TextSchema, task.prompt) || task.prompt.trim().length === 0) {
      throw new RequestValidationError(`tasks[${index}].prompt must be non-empty`);
    }
    if (task.placement !== undefined && !Check(ChildPlacementSchema, task.placement)) {
      throw new RequestValidationError(`tasks[${index}].placement must be tab or split`);
    }
    if (task.role !== undefined && (!Check(TextSchema, task.role) || task.role.trim().length === 0)) {
      throw new RequestValidationError(`tasks[${index}].role must be non-empty`);
    }
    if (task.model !== undefined && !isCanonicalModel(task.model)) {
      throw new RequestValidationError(`tasks[${index}].model must be an exact provider/model-id`);
    }
    if (task.thinking !== undefined && !Check(ChildThinkingLevelSchema, task.thinking)) {
      throw new RequestValidationError(`tasks[${index}].thinking must be a supported thinking level`);
    }
  });
}

function isCanonicalModel(value: string): boolean {
  if (!Check(TextSchema, value) || value !== value.trim()) return false;
  const slash = value.indexOf("/");
  if (slash <= 0 || slash === value.length - 1) return false;
  const provider = value.slice(0, slash);
  const id = value.slice(slash + 1);
  return provider === provider.trim() && id === id.trim() && provider.length > 0 && id.length > 0;
}

export function taskIdFor(index: number): TaskId {
  // SAFETY: This factory is the sole creator of TaskId values and always uses the task-${number} format.
  return `task-${index + 1}` as TaskId;
}

export function childPrompt(taskId: TaskId, task: SpawnTask): string {
  return `<!-- pi-herdr-task:${taskId} -->\nYou are a fresh Pi instance handling one bounded task for a Parent Pi.\n\nTask:\n${task.prompt}\n\nOperate in the current checkout and respect any configured Child role, including read-only constraints. Other Pi instances may be working concurrently.\nReturn a concise final answer containing:\n- what you found or changed;\n- verification performed;\n- unresolved issues or interference observed.`;
}

import { readFileSync, readdirSync } from "node:fs";
import { extname, join } from "node:path";
import { getAgentDir } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";
import { Check } from "typebox/value";
import { parseDocument as parseYamlDocument } from "yaml";
import type {
  ChildRuntimeSelection,
  ChildThinkingLevel,
  ModelReference,
  ParentContext,
  SelectionSource,
  SpawnTask,
} from "./domain.js";

export type ConfiguredModel = string | string[];

export interface ChildRuntimeDefaults {
  model?: ConfiguredModel;
  thinking?: ChildThinkingLevel;
}

export interface ChildRole extends ChildRuntimeDefaults {
  description?: string;
  prompt: string;
}

export interface ChildRolesConfig {
  defaults: ChildRuntimeDefaults;
  roles: Record<string, ChildRole>;
}

interface OrchestratorConfig {
  enabled: boolean;
}

export interface HerdrSubagentsConfig extends ChildRolesConfig {
  orchestrator: OrchestratorConfig;
}

export type ChildRolesConfigLoadResult =
  | { ok: true; path: string; config: HerdrSubagentsConfig }
  | { ok: false; path: string; error: string };

export interface ModelRoutingContext {
  config: ChildRolesConfig;
  availableModels: readonly ModelReference[];
}

interface ChildRuntimeFailure {
  ok: false;
  code: "role_not_found" | "model_routing_failed";
  message: string;
  selection?: Omit<ChildRuntimeSelection, "rolePrompt">;
}

export type ChildRuntimeResolution = { ok: true; selection: ChildRuntimeSelection } | ChildRuntimeFailure;

interface ConfigObject {
  readonly [key: string]: ConfigInput;
}

type ConfigInput = string | number | boolean | null | ConfigInput[] | ConfigObject;

interface RoleFrontmatter {
  description?: string;
  model?: ConfiguredModel;
  thinking?: ChildThinkingLevel;
}

class ConfigSourceError extends Error {
  constructor(
    readonly path: string,
    cause: unknown,
  ) {
    super(cause instanceof Error ? cause.message : String(cause));
  }
}

interface Selection<T> {
  value: T | undefined;
  source?: SelectionSource;
}

const ObjectSchema = Type.Object({}, { additionalProperties: true });
const ArraySchema = Type.Array(Type.Unknown());
const ThinkingLevelSchema = Type.Union([
  Type.Literal("off"),
  Type.Literal("minimal"),
  Type.Literal("low"),
  Type.Literal("medium"),
  Type.Literal("high"),
  Type.Literal("xhigh"),
  Type.Literal("max"),
]);
const THINKING_LEVELS: readonly ChildThinkingLevel[] = ["off", "minimal", "low", "medium", "high", "xhigh", "max"];

export function loadChildRolesConfig(path = join(getAgentDir(), "herdr-subagents.json")): ChildRolesConfigLoadResult {
  const rolesPath = rolesDirectoryFor(path);
  let globalConfig: Omit<HerdrSubagentsConfig, "roles"> = { orchestrator: { enabled: false }, defaults: {} };

  try {
    const value: ConfigInput = JSON.parse(readFileSync(path, "utf8"));
    globalConfig = parseConfig(value, rolesPath);
  } catch (error) {
    if (!(error instanceof Error) || !isMissing(error))
      return { ok: false, path, error: error instanceof Error ? error.message : String(error) };
  }

  try {
    return { ok: true, path, config: { ...globalConfig, roles: loadRolesDirectory(rolesPath) } };
  } catch (error) {
    const source = error instanceof ConfigSourceError ? error.path : rolesPath;
    return { ok: false, path: source, error: error instanceof Error ? error.message : String(error) };
  }
}

export function resolveChildRuntime(input: {
  task: SpawnTask;
  parent: ParentContext;
  routing: ModelRoutingContext;
}): ChildRuntimeResolution {
  const roleName = input.task.role;
  const hasRole = roleName !== undefined && Object.prototype.hasOwnProperty.call(input.routing.config.roles, roleName);
  const role = hasRole ? input.routing.config.roles[roleName] : undefined;
  if (roleName !== undefined && !hasRole) {
    return { ok: false, code: "role_not_found", message: `Child role ${JSON.stringify(roleName)} is not configured` };
  }

  const modelChoice = select<ConfiguredModel>(
    input.task.model,
    role?.model,
    input.routing.config.defaults.model,
    input.parent.model && `${input.parent.model.provider}/${input.parent.model.id}`,
  );
  const selectedModel = selectAvailableModel(modelChoice, input.routing.availableModels);
  const thinkingChoice = select(
    input.task.thinking,
    role?.thinking,
    input.routing.config.defaults.thinking,
    input.parent.thinkingLevel,
  );
  const selection: ChildRuntimeSelection = {};
  if (selectedModel) {
    selection.model = selectedModel;
    selection.modelSource = modelChoice.source;
  }
  if (thinkingChoice.value) {
    selection.thinkingLevel = thinkingChoice.value;
    selection.thinkingSource = thinkingChoice.source;
  }
  if (role) selection.rolePrompt = role.prompt;

  if (modelChoice.value && !selectedModel) {
    const visibleSelection = withoutRolePrompt(selection);
    if (modelChoice.source === "role") {
      const { model: _, modelSource: __, ...redactedSelection } = visibleSelection;
      const failure: ChildRuntimeFailure = {
        ok: false,
        code: "model_routing_failed",
        message: "The model configured for the requested Child role is not available",
      };
      if (Object.keys(redactedSelection).length) failure.selection = redactedSelection;
      return failure;
    }
    const failure: ChildRuntimeFailure = {
      ok: false,
      code: "model_routing_failed",
      message: Array.isArray(modelChoice.value)
        ? "The configured default Child model is not available"
        : `Requested Child model ${modelChoice.value} is not available`,
    };
    if (Object.keys(visibleSelection).length) failure.selection = visibleSelection;
    return failure;
  }
  return { ok: true, selection };
}

export function roleGuidance(config: ChildRolesConfig): string | undefined {
  const roles = Object.entries(config.roles);
  if (!roles.length) return undefined;
  return `Configured Child Roles: ${roles.map(([name, role]) => (role.description ? `${name} (${role.description})` : name)).join("; ")}`;
}

function rolesDirectoryFor(configPath: string): string {
  const extension = extname(configPath);
  return join(extension ? configPath.slice(0, -extension.length) : configPath, "roles");
}

function loadRolesDirectory(path: string): Record<string, ChildRole> {
  let entries;
  try {
    entries = readdirSync(path, { withFileTypes: true });
  } catch (error) {
    if (error instanceof Error && isMissing(error)) return {};
    throw new ConfigSourceError(path, error);
  }

  const roles: [string, ChildRole][] = [];
  for (const entry of entries.sort((left, right) => (left.name < right.name ? -1 : left.name > right.name ? 1 : 0))) {
    if (!entry.isFile() || !entry.name.endsWith(".md")) continue;
    const name = entry.name.slice(0, -3);
    const documentPath = join(path, entry.name);
    try {
      if (!nonWhitespace(name)) throw new Error("role names must be non-whitespace strings");
      roles.push([name, parseRoleDocument(readFileSync(documentPath, "utf8"), documentPath)]);
    } catch (error) {
      throw new ConfigSourceError(documentPath, error);
    }
  }
  return Object.fromEntries(roles);
}

function parseRoleDocument(contents: string, path: string): RoleFrontmatter & { prompt: string } {
  let frontmatter: RoleFrontmatter = {};
  let prompt = contents;
  const openingLength = contents.startsWith("---\r\n")
    ? 5
    : contents.startsWith("---\n")
      ? 4
      : contents === "---"
        ? 3
        : 0;

  if (openingLength) {
    let lineStart = openingLength;
    let closingStart = -1;
    let bodyStart = -1;
    while (lineStart <= contents.length) {
      const newline = contents.indexOf("\n", lineStart);
      const lineEnd = newline === -1 ? contents.length : newline;
      const line = contents.slice(lineStart, lineEnd).replace(/\r$/, "");
      if (line === "---") {
        closingStart = lineStart;
        bodyStart = newline === -1 ? contents.length : newline + 1;
        break;
      }
      if (newline === -1) break;
      lineStart = newline + 1;
    }
    if (closingStart === -1) throw new Error(`Unterminated YAML frontmatter in ${path}`);
    const document = parseYamlDocument(contents.slice(openingLength, closingStart), {
      version: "1.2",
      uniqueKeys: true,
      customTags: [],
    });
    const yamlProblem = document.errors[0] ?? document.warnings[0];
    if (yamlProblem) throw yamlProblem;
    const value: unknown = document.toJS({ maxAliasCount: 100 });
    if (value !== null && value !== undefined && !Check(ObjectSchema, value))
      throw new Error("frontmatter must be an object");
    // SAFETY: YAML returned nullish empty frontmatter or TypeBox verified an object with ConfigInput-compatible fields.
    frontmatter = parseRoleFrontmatter(value as ConfigObject | null | undefined, "frontmatter");
    prompt = contents.slice(bodyStart);
  }

  return { ...frontmatter, prompt: parseNonWhitespace(prompt.trim(), "prompt") };
}

function parseRoleFrontmatter(value: ConfigObject | null | undefined, name: string): RoleFrontmatter {
  if (value === null || value === undefined) return {};
  const metadata = parseObject(value, name);
  rejectUnsupported(metadata, ["description", "model", "thinking"], name);
  const result: RoleFrontmatter = {};
  if (metadata.description !== undefined)
    result.description = parseNonWhitespace(metadata.description, `${name}.description`);
  if (metadata.model !== undefined) result.model = validateModel(metadata.model, `${name}.model`);
  if (metadata.thinking !== undefined) result.thinking = validateThinking(metadata.thinking, `${name}.thinking`);
  return result;
}

function parseConfig(value: ConfigInput, rolesPath: string): Omit<HerdrSubagentsConfig, "roles"> {
  const config = parseObject(value, "config");
  if (Object.prototype.hasOwnProperty.call(config, "roles"))
    throw new Error(`config.roles is no longer supported; move each role to ${join(rolesPath, "<name>.md")}`);
  rejectUnsupported(config, ["orchestrator", "defaults"], "config");
  const orchestrator = config.orchestrator === undefined ? { enabled: false } : parseOrchestrator(config.orchestrator);
  const defaults = config.defaults === undefined ? {} : parseDefaults(config.defaults, "defaults");
  return { orchestrator, defaults };
}

function parseOrchestrator(value: ConfigInput): OrchestratorConfig {
  const orchestrator = parseObject(value, "orchestrator");
  rejectUnsupported(orchestrator, ["enabled"], "orchestrator");
  if (!Check(Type.Boolean(), orchestrator.enabled)) throw new Error("orchestrator.enabled must be a boolean");
  return { enabled: orchestrator.enabled };
}

function parseDefaults(value: ConfigInput, name: string): ChildRuntimeDefaults {
  const defaults = parseObject(value, name);
  rejectUnsupported(defaults, ["model", "thinking"], name);
  const result: ChildRuntimeDefaults = {};
  if (defaults.model !== undefined) result.model = validateModel(defaults.model, `${name}.model`);
  if (defaults.thinking !== undefined) result.thinking = validateThinking(defaults.thinking, `${name}.thinking`);
  return result;
}

function validateModel(value: ConfigInput, name: string): ConfiguredModel {
  if (Check(ArraySchema, value)) {
    if (!value.length) throw new Error(`${name} must be a non-empty array of exact provider/model-id strings`);
    return value.map((candidate, index) => validateModelReference(candidate, `${name}[${index}]`));
  }
  return validateModelReference(value, name);
}

function validateModelReference(value: ConfigInput, name: string): string {
  if (!nonWhitespace(value) || value !== value.trim() || !parseModel(value))
    throw new Error(`${name} must be an exact provider/model-id`);
  return value;
}

function validateThinking(value: ConfigInput, name: string): ChildThinkingLevel {
  if (!Check(ThinkingLevelSchema, value)) throw new Error(`${name} must be one of ${THINKING_LEVELS.join(", ")}`);
  return value;
}

function parseModel(value: string): ModelReference | undefined {
  const slash = value.indexOf("/");
  if (slash < 1 || slash === value.length - 1) return undefined;
  const provider = value.slice(0, slash);
  const id = value.slice(slash + 1);
  return nonWhitespace(provider) && nonWhitespace(id) && provider === provider.trim() && id === id.trim()
    ? { provider, id }
    : undefined;
}

function selectAvailableModel(
  choice: Selection<ConfiguredModel>,
  availableModels: readonly ModelReference[],
): ModelReference | undefined {
  if (choice.value === undefined) return undefined;
  const candidates = Array.isArray(choice.value) ? choice.value : [choice.value];
  if (choice.source === "parent") return parseModel(candidates[0]);
  return candidates
    .map(parseModel)
    .find(
      (candidate): candidate is ModelReference =>
        candidate !== undefined &&
        availableModels.some((model) => model.provider === candidate.provider && model.id === candidate.id),
    );
}

function select<T>(
  explicit: T | undefined,
  role: T | undefined,
  defaults: T | undefined,
  parent: T | undefined,
): Selection<T> {
  if (explicit !== undefined) return { value: explicit, source: "explicit" };
  if (role !== undefined) return { value: role, source: "role" };
  if (defaults !== undefined) return { value: defaults, source: "default" };
  return parent === undefined ? { value: undefined } : { value: parent, source: "parent" };
}

function withoutRolePrompt(selection: ChildRuntimeSelection): Omit<ChildRuntimeSelection, "rolePrompt"> {
  const { rolePrompt: _, ...visible } = selection;
  return visible;
}

function parseObject(value: ConfigInput, name: string): ConfigObject {
  if (!Check(ObjectSchema, value)) throw new Error(`${name} must be an object`);
  // SAFETY: TypeBox verified that the value is an object, and ConfigInput's only object member is ConfigObject.
  return value as ConfigObject;
}

function rejectUnsupported(value: ConfigObject, supported: string[], name: string): void {
  for (const key of Object.keys(value))
    if (!supported.includes(key)) throw new Error(`${name}.${key} is not supported`);
}

function nonWhitespace(value: ConfigInput): value is string {
  return Check(Type.String(), value) && value.trim().length > 0;
}

function parseNonWhitespace(value: ConfigInput | undefined, name: string): string {
  if (value === undefined || !nonWhitespace(value)) throw new Error(`${name} must be a non-whitespace string`);
  return value;
}

function isMissing(error: Error): boolean {
  return error instanceof Error && "code" in error && error.code === "ENOENT";
}

export function emptyChildRolesConfig(): ChildRolesConfig {
  return { defaults: {}, roles: {} };
}

import { randomUUID } from "node:crypto";
import {
  childPrompt,
  type BatchProgress,
  type ChildResult,
  type ParentContext,
  type SpawnBatchRequest,
  type SpawnBatchResult,
  taskIdFor,
  validateSpawnBatchRequest,
} from "./domain.js";
import { emptyChildRolesConfig, resolveChildRuntime, type ModelRoutingContext } from "./model-routing.js";
import { StartChildError, type ChildHost } from "./herdr/host.js";
import type { ChildResultReader } from "./results.js";

export interface BatchRunner {
  run(
    request: SpawnBatchRequest,
    context: ParentContext,
    routing: ModelRoutingContext,
    options?: { signal?: AbortSignal; onProgress?: (progress: BatchProgress) => void },
  ): Promise<SpawnBatchResult>;
}

export class ConcurrentBatchRunner implements BatchRunner {
  constructor(
    private readonly host: ChildHost,
    private readonly reader: ChildResultReader,
  ) {}

  async run(
    request: SpawnBatchRequest,
    context: ParentContext,
    routing: ModelRoutingContext = { config: emptyChildRolesConfig(), availableModels: [] },
    options: { signal?: AbortSignal; onProgress?: (progress: BatchProgress) => void } = {},
  ): Promise<SpawnBatchResult> {
    validateSpawnBatchRequest(request);
    const total = request.tasks.length;
    options.onProgress?.({ completed: 0, total, results: [] });
    let parent;
    try {
      parent = await this.host.inspect(options.signal);
      await this.host.renameParent(parent, context, options.signal);
    } catch (error) {
      const result = options.signal?.aborted
        ? this.abortBeforeStart(request)
        : this.inspectFailure(request, messageOf(error));
      options.onProgress?.({ completed: total, total, results: [...result.results] });
      return result;
    }

    const settled: Array<ChildResult | undefined> = Array.from({ length: total });
    const snapshot = () => {
      const results = settled.filter((result): result is ChildResult => result !== undefined);
      options.onProgress?.({ completed: results.length, total, results });
    };
    const results = await Promise.all(
      request.tasks.map(async (task, requestIndex) => {
        const result = await this.runTask(task, requestIndex, context, routing, parent, options.signal);
        settled[requestIndex] = result;
        snapshot();
        return result;
      }),
    );
    return { requested: total, results };
  }

  private async runTask(
    task: SpawnBatchRequest["tasks"][number],
    requestIndex: number,
    context: ParentContext,
    routing: ModelRoutingContext,
    parent: Awaited<ReturnType<ChildHost["inspect"]>>,
    signal: AbortSignal | undefined,
  ): Promise<ChildResult> {
    const taskId = taskIdFor(requestIndex);
    const resolution = resolveChildRuntime({ task, parent: context, routing });
    const base: Omit<ChildResult, "status" | "error"> = {
      taskId,
      requestIndex,
      truncated: false,
      paneClosed: false,
    };
    if (task.role !== undefined) base.role = task.role;
    if (resolution.ok) base.selection = visibleSelection(resolution.selection);
    else if (resolution.selection) base.selection = resolution.selection;
    if (!resolution.ok) {
      const result: ChildResult = {
        ...base,
        status: "failed",
        error: { code: resolution.code, message: resolution.message },
      };
      return result;
    }
    const childContext: ParentContext = {
      ...context,
      model: resolution.selection.model ?? context.model,
      thinkingLevel: resolution.selection.thinkingLevel ?? context.thinkingLevel,
    };
    let child;
    try {
      child = await this.host.start(
        {
          taskId,
          placement: task.placement ?? "tab",
          sessionId: randomUUID(),
          context: childContext,
          rolePrompt: resolution.selection.rolePrompt,
          parent,
        },
        signal,
      );
    } catch (error) {
      const childFields = fieldsForStartError(error);
      const result: ChildResult = {
        ...base,
        ...childFields,
        status: signal?.aborted ? "parent_aborted" : "failed",
        error: signal?.aborted
          ? { code: "parent_aborted", message: "Parent stopped waiting before child startup completed" }
          : { code: "start_failed", message: messageOf(error) },
      };
      return result;
    }
    const childFields = { sessionId: child.sessionId, sessionPath: child.sessionPath, location: child.location };
    const settlement = await raceAbort(this.host.prompt(child, childPrompt(taskId, task)), signal).catch((error) => ({
      error,
    }));
    if (!settlement) {
      const result: ChildResult = {
        ...base,
        ...childFields,
        status: "parent_aborted",
        error: { code: "parent_aborted", message: "Parent stopped waiting; child remains open" },
      };
      return result;
    }
    if ("error" in settlement) {
      const result: ChildResult = {
        ...base,
        ...childFields,
        status: "failed",
        error: { code: "prompt_failed", message: messageOf(settlement.error) },
      };
      return result;
    }
    if (settlement.status === "blocked") {
      const result: ChildResult = {
        ...base,
        ...childFields,
        status: "blocked",
        error: { code: "blocked", message: "Child requires input and remains open" },
      };
      return result;
    }
    if (!child.sessionPath) {
      const result: ChildResult = {
        ...base,
        ...childFields,
        status: "unattributable",
        error: { code: "result_unreadable", message: "Child session path was not reported" },
      };
      return result;
    }
    try {
      const answer = await this.reader.read({
        sessionPath: child.sessionPath,
        taskId,
        baselineEntryId: child.baselineEntryId,
        maxChars: 20_000,
      });
      let paneClosed = false;
      try {
        await this.host.close(child);
        paneClosed = true;
      } catch {
        // The answer is already attributed; a changed or unavailable occupant must remain visible.
      }
      const result: ChildResult = {
        ...base,
        ...childFields,
        status: "succeeded",
        summary: answer.summary,
        truncated: answer.truncated,
        paneClosed,
      };
      return result;
    } catch (error) {
      const result: ChildResult = {
        ...base,
        ...childFields,
        status: "unattributable",
        error: { code: "result_unreadable", message: messageOf(error) },
      };
      return result;
    }
  }

  private inspectFailure(request: SpawnBatchRequest, message: string): SpawnBatchResult {
    return {
      requested: request.tasks.length,
      results: request.tasks.map((_, requestIndex) => ({
        taskId: taskIdFor(requestIndex),
        requestIndex,
        status: "failed",
        truncated: false,
        paneClosed: false,
        error: { code: "start_failed", message },
      })),
    };
  }

  private abortBeforeStart(request: SpawnBatchRequest): SpawnBatchResult {
    return {
      requested: request.tasks.length,
      results: request.tasks.map((_, requestIndex) => ({
        taskId: taskIdFor(requestIndex),
        requestIndex,
        status: "parent_aborted",
        truncated: false,
        paneClosed: false,
        error: { code: "parent_aborted", message: "Parent stopped waiting before batch startup" },
      })),
    };
  }
}

async function raceAbort<T>(promise: Promise<T>, signal?: AbortSignal): Promise<T | undefined> {
  if (!signal) return promise;
  if (signal.aborted) return undefined;
  return new Promise<T | undefined>((resolve, reject) => {
    const abort = () => resolve(undefined);
    signal.addEventListener("abort", abort, { once: true });
    promise.then(
      (value) => {
        signal.removeEventListener("abort", abort);
        resolve(value);
      },
      (error) => {
        signal.removeEventListener("abort", abort);
        reject(error);
      },
    );
  });
}

function visibleSelection(
  selection: import("./domain.js").ChildRuntimeSelection,
): Omit<import("./domain.js").ChildRuntimeSelection, "rolePrompt"> {
  const { rolePrompt: _, ...visible } = selection;
  return visible;
}

function fieldsForStartError(cause: unknown): Pick<ChildResult, "sessionId" | "sessionPath" | "location"> {
  if (!(cause instanceof StartChildError) || !cause.child) return {};
  return {
    sessionId: cause.child.sessionId,
    sessionPath: cause.child.sessionPath,
    location: cause.child.location,
  };
}

function messageOf(cause: unknown): string {
  return cause instanceof Error ? cause.message : String(cause);
}

import type { ExtensionAPI, Theme, ThemeColor } from "@earendil-works/pi-coding-agent";
import { StringEnum } from "@earendil-works/pi-ai";
import { Text } from "@earendil-works/pi-tui";
import { Type, type Static } from "typebox";
import type { BatchRunner } from "./batch.js";
import type { BatchProgress, ChildResult, SpawnBatchResult, SpawnTask } from "./domain.js";
import { taskIdFor } from "./domain.js";
import { roleGuidance, type ChildRolesConfigLoadResult } from "./model-routing.js";

const SpawnTaskSchema = Type.Object({
  prompt: Type.String({ minLength: 1, description: "One independent, bounded task for a fresh Pi" }),
  placement: Type.Optional(
    StringEnum(["tab", "split"] as const, { description: "Visible child placement; defaults to tab" }),
  ),
  role: Type.Optional(Type.String({ minLength: 1, description: "Configured Child Role name" })),
  model: Type.Optional(Type.String({ minLength: 1, description: "Exact provider/model override" })),
  thinking: Type.Optional(StringEnum(["off", "minimal", "low", "medium", "high", "xhigh", "max"] as const)),
});

export const SpawnPiSchema = Type.Object({
  tasks: Type.Array(SpawnTaskSchema, { minItems: 1, maxItems: 8, description: "One to eight independent tasks" }),
});

export type SpawnPiToolInput = Static<typeof SpawnPiSchema>;

type SpawnPiDisplayDetails =
  | { phase: "working"; progress: BatchProgress }
  | { phase: "finished"; result: SpawnBatchResult };

type ChildDisplayState = "working" | "complete" | "needs_input" | "incomplete";
type BatchDisplayState = "working" | "complete" | "needs_input" | "incomplete";

export function registerSpawnPiTool(
  pi: ExtensionAPI,
  runner: BatchRunner,
  getParentLabel: () => string,
  configResult: ChildRolesConfigLoadResult,
): void {
  pi.registerTool<typeof SpawnPiSchema, SpawnPiDisplayDetails>({
    name: "spawn_pi",
    label: "Spawn Pi",
    description:
      "Run 1–8 independent bounded tasks concurrently in fresh visible Pi sessions hosted by Herdr. Children share the current checkout and cannot invoke spawn_pi.",
    promptSnippet: "Offload independent repository exploration or bounded work to fresh visible Pi sessions",
    promptGuidelines: [
      "Use spawn_pi only for 1–8 independent tasks; children share the checkout and may interfere with concurrent edits.",
      ...(configResult.ok && roleGuidance(configResult.config) ? [roleGuidance(configResult.config)!] : []),
    ],
    parameters: SpawnPiSchema,
    async execute(_toolCallId, params, signal, onUpdate, ctx) {
      if (!configResult.ok)
        throw new Error(`Invalid Child Roles config at ${configResult.path}: ${configResult.error}`);
      const result = await runner.run(
        { tasks: params.tasks },
        {
          cwd: ctx.cwd,
          parentLabel: getParentLabel(),
          model: ctx.model ? { provider: ctx.model.provider, id: ctx.model.id } : undefined,
          thinkingLevel: ctx.thinkingLevel,
        },
        {
          config: configResult.config,
          availableModels: ctx.modelRegistry
            .getAvailable()
            .map((model) => ({ provider: model.provider, id: model.id })),
        },
        {
          signal,
          onProgress(progress) {
            onUpdate?.({
              content: [{ type: "text", text: summarizeProgress(progress) }],
              details: { phase: "working", progress } satisfies SpawnPiDisplayDetails,
            });
          },
        },
      );
      return {
        content: [{ type: "text", text: summarize(result) }],
        details: { phase: "finished", result } satisfies SpawnPiDisplayDetails,
      };
    },
    renderCall(args, theme) {
      const tasks = requestedTasks(args);
      const count = tasks?.length;
      return new Text(
        theme.fg("toolTitle", theme.bold("spawn_pi")) +
          (count === undefined ? "" : theme.fg("accent", ` ${count} task${count === 1 ? "" : "s"}`)),
        0,
        0,
      );
    },
    renderResult(result, { expanded, isPartial }, theme, context) {
      const details = displayDetails(result.details, isPartial);
      if (!details) return new Text(rawText(result.content), 0, 0);

      const tasks = requestedTasks(context.args);
      const progress = details.phase === "working" ? details.progress : undefined;
      const batch = details.phase === "finished" ? details.result : undefined;
      const total = progress?.total ?? batch?.requested ?? tasks?.length ?? 0;
      const settled = new Map<number, ChildResult>();
      for (const result of progress?.results ?? batch?.results ?? []) {
        settled.set(result.requestIndex, result);
      }
      const state = batchDisplayState(details);
      const header =
        details.phase === "working"
          ? `working · ${details.progress.completed} of ${details.progress.total} settled`
          : `${stateIcon(state)} ${finalBatchStatus(details.result, state)}`;
      const lines = [theme.fg(stateColor(state), header)];
      for (let requestIndex = 0; requestIndex < total; requestIndex += 1) {
        const task = tasks?.[requestIndex];
        lines.push(renderChild(taskIdFor(requestIndex), task?.role, settled.get(requestIndex), expanded, theme));
      }
      return new Text(lines.join("\n"), 0, 0);
    },
  });
}

function childDisplayState(result: ChildResult | undefined): ChildDisplayState {
  if (!result) return "working";
  if (result.status === "succeeded") return "complete";
  if (result.status === "blocked") return "needs_input";
  return "incomplete";
}

function batchDisplayState(details: SpawnPiDisplayDetails): BatchDisplayState {
  if (details.phase === "working") return "working";
  const { requested, results } = details.result;
  if (results.length !== requested) return "incomplete";
  const states = results.map(childDisplayState);
  if (states.every((state) => state === "complete")) return "complete";
  if (states.every((state) => state === "complete" || state === "needs_input")) return "needs_input";
  return "incomplete";
}

function shortReason(result: ChildResult): string | undefined {
  if (result.status === "unattributable") return "result unreadable";
  if (result.status === "parent_aborted") return "parent stopped waiting";
  if (result.status !== "failed") return undefined;
  switch (result.error?.code) {
    case "role_not_found":
      return "role not found";
    case "model_routing_failed":
      return "model unavailable";
    case "start_failed":
      return "could not start";
    case "prompt_failed":
      return "prompt failed";
    case "result_unreadable":
      return "result unreadable";
    case "parent_aborted":
      return "parent stopped waiting";
    default:
      return "unknown failure";
  }
}

function summarizeProgress(progress: BatchProgress): string {
  return `spawn_pi: working · ${progress.completed} of ${progress.total} settled`;
}

function summarize(result: SpawnBatchResult): string {
  const details: SpawnPiDisplayDetails = { phase: "finished", result };
  const batchState = batchDisplayState(details);
  const lines = [`spawn_pi: ${stateIcon(batchState)} ${finalBatchStatus(result, batchState)}`];
  for (const child of orderedResults(result.results)) {
    const state = childDisplayState(child);
    const role = presentationRole(child.role);
    let line = `${stateIcon(state)} ${child.taskId}${role ? ` [${role}]` : ""}`;
    if (state !== "complete") line += `: ${displayLabel(state)}`;
    const reason = shortReason(child);
    if (reason) line += ` · ${reason}`;
    if (child.sessionId) line += ` · session ${child.sessionId}`;
    if (child.error && state !== "complete") line += ` · ${child.error.message}`;
    lines.push(line);
  }
  return lines.join("\n");
}

function renderChild(
  taskId: string,
  requestedRole: string | undefined,
  result: ChildResult | undefined,
  expanded: boolean,
  theme: Theme,
): string {
  const state = childDisplayState(result);
  const role = presentationRole(requestedRole);
  let line = `${theme.fg(stateColor(state), stateIcon(state))} ${theme.fg("toolTitle", taskId)}${role ? theme.fg("muted", ` [${role}]`) : ""}`;
  if (state !== "complete") line += ` ${theme.fg(stateColor(state), displayLabel(state))}`;
  const reason = result && shortReason(result);
  if (state === "incomplete" && reason) line += theme.fg("muted", ` · ${reason}`);
  const location = result && !result.paneClosed ? locationText(result) : undefined;
  if (state === "needs_input" && location) line += theme.fg("muted", ` · ${location}`);
  if (!expanded || !result) return line;

  const details: string[] = [];
  if (state === "complete" && result.summary) details.push(theme.fg("toolOutput", result.summary));
  if (state === "complete" && result.truncated) details.push(theme.fg("muted", "summary truncated"));
  if (state === "needs_input" || state === "incomplete") {
    if (result.error?.message) details.push(theme.fg("error", result.error.message));
  }
  if (location && !(state === "needs_input" && location)) details.push(theme.fg("muted", `location: ${location}`));
  if (result.selection?.model)
    details.push(theme.fg("muted", `model: ${result.selection.model.provider}/${result.selection.model.id}`));
  if (result.selection?.thinkingLevel) details.push(theme.fg("muted", `thinking: ${result.selection.thinkingLevel}`));
  if (result.selection?.modelSource)
    details.push(theme.fg("muted", `model selection: ${result.selection.modelSource}`));
  if (result.selection?.thinkingSource)
    details.push(theme.fg("muted", `thinking selection: ${result.selection.thinkingSource}`));
  if (result.sessionId) details.push(theme.fg("muted", `session: ${result.sessionId}`));
  return details.length ? `${line}\n${details.join("\n")}` : line;
}

function displayDetails(
  value: SpawnPiDisplayDetails | SpawnBatchResult | undefined,
  isPartial: boolean,
): SpawnPiDisplayDetails | undefined {
  if (value === undefined) return undefined;
  if ("phase" in value) return value;
  return isPartial ? undefined : { phase: "finished", result: value };
}

function requestedTasks(value: { tasks?: SpawnTask[] }): SpawnTask[] | undefined {
  return value.tasks;
}

function rawText(content: readonly { type: string; text?: string }[]): string {
  const text = content.find((part) => part.type === "text");
  return text?.text ?? "spawn_pi finished";
}

function successfulCount(result: SpawnBatchResult | undefined): number {
  return result?.results.filter((child) => child.status === "succeeded").length ?? 0;
}

function finalBatchStatus(result: SpawnBatchResult, state: BatchDisplayState): string {
  const completed = successfulCount(result);
  if (state === "complete")
    return `${completed} of ${result.requested} ${result.requested === 1 ? "task" : "tasks"} complete`;
  return `${displayLabel(state)} · ${completed} of ${result.requested} complete`;
}

function orderedResults(results: ChildResult[]): ChildResult[] {
  return [...results].sort((left, right) => left.requestIndex - right.requestIndex);
}

function presentationRole(role: string | undefined): string | undefined {
  if (role === undefined) return undefined;
  const value = Array.from(role, (character) => (isControlCharacter(character) ? " " : character))
    .join("")
    .replace(/\s+/g, " ")
    .trim();
  return value || undefined;
}

function isControlCharacter(character: string): boolean {
  const code = character.charCodeAt(0);
  return code <= 0x1f || (code >= 0x7f && code <= 0x9f);
}

function locationText(result: ChildResult): string | undefined {
  return result.location ? `${result.location.tabId}/${result.location.paneId}` : undefined;
}

function displayLabel(state: ChildDisplayState | BatchDisplayState): string {
  return state === "needs_input" ? "needs input" : state;
}

function stateIcon(state: ChildDisplayState | BatchDisplayState): string {
  return state === "working" ? "◌" : state === "complete" ? "✓" : state === "needs_input" ? "!" : "×";
}

function stateColor(state: ChildDisplayState | BatchDisplayState): ThemeColor {
  return state === "working"
    ? "accent"
    : state === "complete"
      ? "success"
      : state === "needs_input"
        ? "warning"
        : "error";
}

import assert from "node:assert/strict";
import { mkdirSync, mkdtempSync, rmSync, symlinkSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
import { loadChildRolesConfig, resolveChildRuntime, roleGuidance } from "../../src/model-routing.js";

const parent = { cwd: "/repo", model: { provider: "parent", id: "unavailable" }, thinkingLevel: "high" as const };
const config = {
  defaults: { model: "default/model", thinking: "medium" as const },
  roles: {
    explore: {
      prompt: "Explore the repository.",
      description: "Read-only exploration",
      model: "role/model",
      thinking: "low" as const,
    },
  },
};

function errorOf(result: ReturnType<typeof loadChildRolesConfig>): string {
  assert.equal(result.ok, false);
  return result.error;
}

function resolve(
  task: Parameters<typeof resolveChildRuntime>[0]["task"],
  availableModels = [
    { provider: "default", id: "model" },
    { provider: "role", id: "model" },
    { provider: "explicit", id: "nested/model" },
  ],
) {
  return resolveChildRuntime({ task, parent, routing: { config, availableModels } });
}

test("loads global config and role catalogue independently", () => {
  const directory = mkdtempSync(join(tmpdir(), "child-roles-"));
  const path = join(directory, "custom.config.json");
  const rolesPath = join(directory, "custom.config", "roles");
  try {
    assert.deepEqual(loadChildRolesConfig(path), {
      ok: true,
      path,
      config: { orchestrator: { enabled: false }, defaults: {}, roles: {} },
    });

    mkdirSync(rolesPath, { recursive: true });
    writeFileSync(join(rolesPath, "body-only.md"), "\n  Investigate.\n\n- Keep evidence.\n  ");
    writeFileSync(join(rolesPath, "scalar.md"), "---\nmodel: provider/one\n---\nScalar prompt");
    writeFileSync(join(rolesPath, "empty-metadata.md"), "---\n---\nEmpty metadata prompt");
    writeFileSync(
      join(rolesPath, "explore.md"),
      [
        "---",
        "description: Read-only exploration",
        "model:",
        "  - provider/first",
        "  - provider/a/b",
        "thinking: low",
        "---",
        "",
        "Explore the repository.",
      ].join("\n"),
    );
    let loaded = loadChildRolesConfig(path);
    assert.equal(loaded.ok, true);
    if (loaded.ok) {
      assert.equal(loaded.config.orchestrator.enabled, false);
      assert.deepEqual(loaded.config.roles["body-only"], { prompt: "Investigate.\n\n- Keep evidence." });
      assert.deepEqual(loaded.config.roles.scalar, { model: "provider/one", prompt: "Scalar prompt" });
      assert.deepEqual(loaded.config.roles["empty-metadata"], { prompt: "Empty metadata prompt" });
      assert.deepEqual(loaded.config.roles.explore, {
        description: "Read-only exploration",
        model: ["provider/first", "provider/a/b"],
        thinking: "low",
        prompt: "Explore the repository.",
      });
    }

    writeFileSync(path, JSON.stringify({ orchestrator: { enabled: true }, defaults: { model: "provider/a/b" } }));
    loaded = loadChildRolesConfig(path);
    assert.equal(loaded.ok, true);
    if (loaded.ok) {
      assert.equal(loaded.config.orchestrator.enabled, true);
      assert.equal(loaded.config.defaults.model, "provider/a/b");
      assert.equal(loaded.config.roles.explore.prompt, "Explore the repository.");
    }
  } finally {
    rmSync(directory, { recursive: true, force: true });
  }
});

test("discovers only sorted direct regular exact-.md files", () => {
